-- S10-015：泛微 OA 账号参考映射与严格自动绑定。
-- 生产发布迁移：只写入参考数据和受控触发器，不回填既有账号、不调用外部系统。

CREATE TABLE IF NOT EXISTS iam.eteams_account_reference_mappings (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  v3_username citext NOT NULL,
  expected_display_name text NOT NULL,
  external_subject text NOT NULL,
  external_username text NOT NULL,
  mapping_status text NOT NULL DEFAULT 'auto_match_enabled'
    CHECK (mapping_status IN ('auto_match_enabled', 'review_required', 'disabled')),
  source_version text NOT NULL,
  source_file_row integer NOT NULL CHECK (source_file_row > 0),
  queried_on date NOT NULL,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  row_version bigint NOT NULL DEFAULT 1,
  CHECK (length(btrim(v3_username::text)) BETWEEN 1 AND 200),
  CHECK (length(btrim(expected_display_name)) BETWEEN 1 AND 200),
  CHECK (length(btrim(external_subject)) BETWEEN 1 AND 200),
  CHECK (length(btrim(external_username)) BETWEEN 1 AND 200),
  UNIQUE (source_version, source_file_row)
);

CREATE UNIQUE INDEX IF NOT EXISTS ux_eteams_reference_username
  ON iam.eteams_account_reference_mappings (lower(v3_username::text));
CREATE UNIQUE INDEX IF NOT EXISTS ux_eteams_reference_subject
  ON iam.eteams_account_reference_mappings (external_subject);
CREATE INDEX IF NOT EXISTS idx_eteams_reference_status_username
  ON iam.eteams_account_reference_mappings (mapping_status, lower(v3_username::text));

COMMENT ON TABLE iam.eteams_account_reference_mappings IS
  '泛微 OA 账号参考映射。仅登录名、显示姓名和启用状态全部严格匹配时允许未来账号自动绑定；不回填既有账号。';
COMMENT ON COLUMN iam.eteams_account_reference_mappings.mapping_status IS
  'auto_match_enabled=允许严格自动绑定；review_required=同名或其他冲突待人工核验；disabled=停用参考记录。';

ON CONFLICT (source_version, source_file_row) DO NOTHING;

CREATE TABLE IF NOT EXISTS iam.eteams_identity_auto_match_events (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  reference_mapping_id uuid NOT NULL REFERENCES iam.eteams_account_reference_mappings(id) ON DELETE RESTRICT,
  user_id uuid NOT NULL REFERENCES iam.users(id) ON DELETE RESTRICT,
  external_identity_id uuid REFERENCES iam.external_identities(id) ON DELETE RESTRICT,
  result_code text NOT NULL CHECK (result_code IN ('auto_bound', 'skipped_existing_identity', 'skipped_external_subject_occupied', 'skipped_insert_conflict')),
  operation_code text NOT NULL CHECK (operation_code IN ('insert', 'update')),
  v3_username citext NOT NULL,
  v3_display_name text NOT NULL,
  external_subject text NOT NULL,
  created_at timestamptz NOT NULL DEFAULT now(),
  details_json jsonb NOT NULL DEFAULT '{}'::jsonb CHECK (jsonb_typeof(details_json) = 'object')
);

CREATE INDEX IF NOT EXISTS idx_eteams_auto_match_events_user_created
  ON iam.eteams_identity_auto_match_events(user_id, created_at DESC);
CREATE INDEX IF NOT EXISTS idx_eteams_auto_match_events_result_created
  ON iam.eteams_identity_auto_match_events(result_code, created_at DESC);
COMMENT ON TABLE iam.eteams_identity_auto_match_events IS
  '泛微 OA 账号严格自动匹配事件。只追加成功绑定或明确跳过事实，不保存令牌和外部接口响应。';

CREATE OR REPLACE FUNCTION iam.自动匹配泛微OA身份()
RETURNS trigger
LANGUAGE plpgsql
AS $$
DECLARE
  ref iam.eteams_account_reference_mappings%ROWTYPE;
  inserted_identity iam.external_identities%ROWTYPE;
  auto_match_event_id uuid;
  operation_code text := CASE WHEN TG_OP = 'INSERT' THEN 'insert' ELSE 'update' END;
BEGIN
  IF NEW.status_code <> 'active' THEN
    RETURN NEW;
  END IF;

  SELECT r.* INTO ref
  FROM iam.eteams_account_reference_mappings r
  WHERE lower(r.v3_username::text) = lower(NEW.username::text)
    AND r.expected_display_name = NEW.display_name
    AND r.mapping_status = 'auto_match_enabled'
  LIMIT 1;
  IF NOT FOUND THEN
    RETURN NEW;
  END IF;

  IF EXISTS (
    SELECT 1 FROM iam.external_identities e
    WHERE e.user_id = NEW.id
      AND e.provider_code = 'eteams'
      AND e.status_code = 'active'
  ) THEN
      reference_mapping_id, user_id, result_code, operation_code, v3_username, v3_display_name, external_subject, details_json
    ) VALUES (ref.id, NEW.id, 'skipped_existing_identity', operation_code, NEW.username, NEW.display_name, ref.external_subject, '{}'::jsonb);
    RETURN NEW;
  END IF;

  VALUES (NEW.id, 'eteams', ref.external_subject, ref.external_username, 'active')
  ON CONFLICT DO NOTHING
  RETURNING * INTO inserted_identity;

  IF inserted_identity.id IS NOT NULL THEN
      reference_mapping_id, user_id, external_identity_id, result_code, operation_code, v3_username, v3_display_name, external_subject, details_json
    ) VALUES (
      ref.id, NEW.id, inserted_identity.id, 'auto_bound', operation_code, NEW.username, NEW.display_name, ref.external_subject,
      jsonb_build_object('sourceVersion', ref.source_version, 'sourceFileRow', ref.source_file_row)
    ) RETURNING id INTO auto_match_event_id;

      created_at, request_id, actor_user_id, actor_username, actor_name, actor_role, module_code,
      action_code, target_type, target_id, result_code, message, before_json, after_json, extra_json
    ) VALUES (
      now(), NULL, NULL, 'system', '系统自动匹配', 'system', 'identity',
      'eteams_identity.auto_bound', 'external_identity', inserted_identity.id::text, 'success', '已按登录名与姓名严格匹配并绑定泛微 OA 身份',
      '{}'::jsonb,
      jsonb_build_object('v3Username', NEW.username::text, 'v3DisplayName', NEW.display_name, 'externalSubject', ref.external_subject),
      jsonb_build_object('autoMatchEventId', auto_match_event_id, 'sourceVersion', ref.source_version, 'sourceFileRow', ref.source_file_row)
    );
  ELSIF EXISTS (
    SELECT 1 FROM iam.external_identities e
    WHERE e.provider_code = 'eteams'
      AND e.external_subject = ref.external_subject
      AND e.status_code = 'active'
      AND e.user_id <> NEW.id
  ) THEN
      reference_mapping_id, user_id, result_code, operation_code, v3_username, v3_display_name, external_subject, details_json
    ) VALUES (ref.id, NEW.id, 'skipped_external_subject_occupied', operation_code, NEW.username, NEW.display_name, ref.external_subject, '{}'::jsonb);
  ELSE
      reference_mapping_id, user_id, result_code, operation_code, v3_username, v3_display_name, external_subject, details_json
    ) VALUES (ref.id, NEW.id, 'skipped_insert_conflict', operation_code, NEW.username, NEW.display_name, ref.external_subject, '{}'::jsonb);
  END IF;

  RETURN NEW;
END;
$$;

DROP TRIGGER IF EXISTS trg_iam_users_eteams_auto_match ON iam.users;
CREATE TRIGGER trg_iam_users_eteams_auto_match
AFTER INSERT OR UPDATE OF username, display_name, status_code ON iam.users
FOR EACH ROW
EXECUTE FUNCTION iam.自动匹配泛微OA身份();

COMMENT ON FUNCTION iam.自动匹配泛微OA身份() IS
  '仅对未来新增或更新且状态为active、登录名和姓名与参考表完全匹配的账号新增eteams正式身份；不覆盖已有身份。';
